  const byPerson = new Map(this.people().map((p) => [p.id, countsClaimed(today, p.retiredFrom)]));
  return (c: ClaimView) => (byPerson.get(c.personId) ?? countsClaimed(today))(c);
});
protected readonly claimedTotal = computed(() =>
