  for (const p of this.people()) {
    const split = { ...NO_SPLIT };
    for (const c of this.claimsOf(p.id).filter(countsWithHolds(p.holds, this.todayNow(), p.retiredFrom))) {
      const due = this.claimDue(p, c, dueTerms) ?? 0;
