package net.officefloor.hq.app.sheet;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.Instant;
import java.time.LocalDate;
import java.util.Arrays;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.period.PeriodService;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.snapshot.PersonSnapshotService;
import org.springframework.context.annotation.Lazy;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** Loads sheets by id; a sheet never loaded before is started empty. */
@Service
public class SheetService {

    private final SheetRepository sheets;
    private final Rollup rollup;
    private final Audit audit;

    private final PeriodService periods;
    private final ClaimRepository claims;
    private final PersonSnapshotService snapshots;

    // The period service loads sheets through this one, so it is taken lazily.
    public SheetService(SheetRepository sheets, Rollup rollup, Audit audit, @Lazy PeriodService periods,
            ClaimRepository claims, PersonSnapshotService snapshots) {
        this.sheets = sheets;
        this.snapshots = snapshots;
        this.claims = claims;
        this.rollup = rollup;
        this.audit = audit;
        this.periods = periods;
    }

    /** The sheet with this id, re-read from the store; started empty if it has never been loaded. */
    @Transactional
    public Sheet load(String id, String user) {
        return sheets.findById(id).orElseGet(() -> {
            try {
                return sheets.saveAndFlush(new Sheet(id, user, Instant.now(), LocalDate.now()));
            } catch (DataIntegrityViolationException raced) {
                // Another user started the same sheet at the same moment: theirs stands.
                return sheets.findById(id).orElseThrow(() -> raced);
            }
        });
    }

    /** The sheet's today, or null for a sheet never loaded. */
    @Transactional(readOnly = true)
    public LocalDate today(String id) {
        return sheets.findById(id).map(Sheet::getToday).orElse(null);
    }

    /** Whether the sheet is archived; a sheet never loaded is not. */
    @Transactional(readOnly = true)
    public boolean isArchived(String id) {
        return sheets.findById(id).map(Sheet::isArchived).orElse(false);
    }

    /** Archive the sheet, starting it if it has never been loaded. Who may archive it is checked by the caller;
     *  an archived sheet is refused before it gets here (see {@link ArchiveGuard}), and again under the lock. */
    @Transactional
    public Sheet archive(String id, String user) {
        load(id, user);
        Sheet sheet = sheets.findLockedById(id).orElseThrow();
        if (sheet.isArchived()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The sheet is archived");
        }
        sheet.archive();
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordChangeOnCommit(id, user, "SHEET_ARCHIVED sheet=" + id + " by=" + user);
        return saved;
    }

    /** Set the sheet's today, starting the sheet if it has never been loaded; then close every open period past its
     *  grace days. A change of today first records a SNAPSHOT line per person, in list order, with their due-total on
     *  the day being left (kept as the person's snapshot line), and releases every claim editor's lock on the sheet. */
    @Transactional
    public Sheet setToday(String id, String user, LocalDate today) {
        load(id, user);
        Sheet sheet = sheets.findLockedById(id).orElseThrow();
        Rollup.Figures before = rollup.of(id);
        boolean changed = !today.equals(sheet.getToday());
        if (changed) {
            LocalDate left = sheet.getToday();
            before.people().forEach((personId, figures) -> {
                snapshots.record(id, personId, left, figures.dueTotal(), today);
                audit.recordActingOnCommit(id, user, "SNAPSHOT sheet=" + id + " by=" + user
                        + " name=" + figures.name() + " due-total=" + figures.dueTotal());
            });
        }
        sheet.setToday(today);
        Sheet saved = sheets.saveAndFlush(sheet);
        periods.closePastGrace(saved, user);
        rollup.recordChanges(id, user, before);
        if (changed) {
            // Last, so no claim read before writes its lock back.
            claims.releaseLocks(id);
        }
        return saved;
    }

    /** Record the sheet's clerk limit (null: no limit) from a date (null: the sheet's today), starting the sheet if
     *  it has never been loaded. */
    @Transactional
    public Sheet setClerkLimit(String id, String user, BigDecimal limit, LocalDate from) {
        return record(id, user, Sheet.CLERK_LIMIT, from, limit == null ? null : scaled(limit), false);
    }

    /** Record the sheet's floor from a date (null: the sheet's today), starting the sheet if it has never been
     *  loaded. */
    @Transactional
    public Sheet setFloor(String id, String user, BigDecimal floor, LocalDate from) {
        return record(id, user, Sheet.FLOOR, from, scaled(floor), true);
    }

    /** Record the sheet's terms in days from a date (null: the sheet's today), starting the sheet if it has never
     *  been loaded. */
    @Transactional
    public Sheet setTerms(String id, String user, int terms, LocalDate from) {
        return record(id, user, Sheet.TERMS, from, String.valueOf(terms), false);
    }

    /** Record a grade's own terms in days (null: the sheet's terms) from a date (null: the sheet's today), starting
     *  the sheet if it has never been loaded. */
    @Transactional
    public Sheet setGradeTerms(String id, String user, String grade, Integer terms, LocalDate from) {
        return record(id, user, Sheet.TERMS + "-" + grade, from, terms == null ? null : String.valueOf(terms), false);
    }

/**
 * The figures of a sheet as the screen shows them: each person's claimed, due-total and overdue-total, and the
 * sheet's claimed-total, due-total and overdue-total (the latter two trimmed of the single highest and lowest
 * person's figure when three or more people have one). A change takes the figures before it and, once made, records
 * a ROLLUP line for each person whose figures moved and a TOTALS line when any of the sheet's totals moved.
 */
@Service
public class Rollup {

    /** A person's figures: claimed, due-total and overdue-total, each with two decimals; due-total is "n/a" when they
     *  have none. */
    public record PersonFigures(String name, String claimed, String dueTotal, String overdueTotal) {
    }

    /** A sheet's figures: each person's, by id in the order they were added, and the sheet's totals. */
    public record Figures(Map<Long, PersonFigures> people, String claimedTotal, String dueTotal, String overdueTotal) {
    }

    private static final String NOT_AVAILABLE = "n/a";

    private final SheetRepository sheets;
    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateChains rates;
    private final PeriodRepository periods;
    private final Audit audit;

    public Rollup(SheetRepository sheets, PersonRepository people, ClaimRepository claims, RateChains rates,
            PeriodRepository periods, Audit audit) {
        this.periods = periods;
        this.sheets = sheets;
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.audit = audit;
    }

    /** The sheet's figures as the store holds them now. */
    public Figures of(String sheetId) {
        return of(sheets.findById(sheetId).orElse(null), rates.of(sheetId),
                people.findBySheetIdOrderByPositionAscIdAsc(sheetId), claims.findBySheetIdOrderByListedDescIdDesc(sheetId));
    }

    /** The figures of a sheet holding these rates, people (in list order) and claims (in list order), worked out on
     *  its today: the live sheet's, or one rebuilt as it stood at a moment (none: no sheet). */
    public Figures of(Sheet sheet, RateChain sheetRates, List<Person> sheetPeople, List<Claim> sheetClaims) {
        LocalDate today = sheet == null ? null : sheet.getToday();
        Map<Long, PersonFigures> byPerson = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
        List<BigDecimal> dueFigures = new ArrayList<>();
        List<BigDecimal> overdueFigures = new ArrayList<>();
        for (Person person : sheetPeople) {
            List<Claim> counting = sheetClaims.stream()
                    .filter(c -> c.getPersonId().equals(person.getId()) && person.counts(c, today)
                            && !c.isDeferredOn(today))
                    .toList();
            // Claimed leaves out corrections: claims that correct another; a held claim still counts in it.
            BigDecimal claimed = sheetClaims.stream()
                    .filter(c -> c.getPersonId().equals(person.getId()) && person.countsClaimed(c, today)
                            && !c.isDeferredOn(today) && c.getCorrects() == null)
                    .map(Claim::getAmount)
                    .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
            claimedTotal = claimedTotal.add(claimed);
            // As on screen: with no rate in force today for their grade on the sheet's today, nor for the grade
            // any of their claims is at, and no claim that has a due, the person has no due-total.
            List<BigDecimal> dues = counting.stream()
                    .map(c -> dueOf(c, person.gradeOn(c.getDate()), sheetRates, sheet, sheetClaims))
                    .filter(Objects::nonNull)
                    .toList();
            boolean anyRate = today != null && Stream.concat(Stream.of(person.gradeOn(today)),
                            counting.stream().map(c -> person.gradeOn(c.getDate())))
                    .anyMatch(grade -> sheetRates.inForceOn(grade, today).isPresent());
            String due = NOT_AVAILABLE;
            if (!dues.isEmpty() || anyRate) {
                BigDecimal sum = dues.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
                BigDecimal total = sheet == null ? sum : sheet.capped(sum);
                dueFigures.add(total);
                due = total.toPlainString();
            }
            // As on screen: the dues of the claims that count which are open and due by (plus their grade's grace
            // days) a day before the sheet's today.
            BigDecimal overdue = counting.stream()
                    .filter(c -> today != null && ClaimService.isOverdue(c, sheet, person.gradeOn(c.getDate())))
                    .map(c -> dueOf(c, person.gradeOn(c.getDate()), sheetRates, sheet, sheetClaims))
                    .filter(Objects::nonNull)
                    .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
            overdueFigures.add(overdue);
            byPerson.put(person.getId(),
                    new PersonFigures(person.getName(), claimed.toPlainString(), due, overdue.toPlainString()));
        }
        return new Figures(byPerson, claimedTotal.toPlainString(), trimmedSum(dueFigures).toPlainString(),
                trimmedSum(overdueFigures).toPlainString());
    }

    /** The figures added up, leaving out the single highest and the single lowest when there are three or more. */
    static BigDecimal trimmedSum(List<BigDecimal> figures) {
        BigDecimal sum = figures.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
